-- VCTN Enterprise PostgreSQL DDL v2.0
-- BIGINT Snowflake IDs generated by application. UTC. No tenant_id.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- SYSTEM / ADMIN
CREATE TABLE sys_department (id BIGINT PRIMARY KEY,parent_id BIGINT REFERENCES sys_department(id),department_code VARCHAR(64) NOT NULL,department_name VARCHAR(128) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',sort_order INT NOT NULL DEFAULT 0,description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_department_code ON sys_department(lower(department_code)) WHERE deleted_at IS NULL;
CREATE TABLE sys_user (id BIGINT PRIMARY KEY,username VARCHAR(64) NOT NULL,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(128) NOT NULL,email VARCHAR(320),phone VARCHAR(32),department_id BIGINT REFERENCES sys_department(id),status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',is_super_admin BOOLEAN NOT NULL DEFAULT FALSE,must_change_password BOOLEAN NOT NULL DEFAULT TRUE,password_changed_at TIMESTAMPTZ,password_expires_at TIMESTAMPTZ,failed_login_count INT NOT NULL DEFAULT 0,locked_until TIMESTAMPTZ,last_login_at TIMESTAMPTZ,last_login_ip INET,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_user_username ON sys_user(lower(username)) WHERE deleted_at IS NULL;
CREATE TABLE sys_role (id BIGINT PRIMARY KEY,role_code VARCHAR(64) NOT NULL,role_name VARCHAR(128) NOT NULL,description VARCHAR(500),status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',data_scope VARCHAR(32) NOT NULL DEFAULT 'SELF',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_role_code ON sys_role(lower(role_code)) WHERE deleted_at IS NULL;
CREATE TABLE sys_user_role (user_id BIGINT REFERENCES sys_user(id),role_id BIGINT REFERENCES sys_role(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,role_id));
CREATE TABLE sys_role_inheritance (parent_role_id BIGINT REFERENCES sys_role(id),child_role_id BIGINT REFERENCES sys_role(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(parent_role_id,child_role_id),CHECK(parent_role_id<>child_role_id));
CREATE TABLE sys_permission (id BIGINT PRIMARY KEY,permission_code VARCHAR(128) NOT NULL,permission_name VARCHAR(128) NOT NULL,permission_type VARCHAR(32) NOT NULL,resource_type VARCHAR(64),resource_code VARCHAR(128),parent_id BIGINT REFERENCES sys_permission(id),status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',sort_order INT NOT NULL DEFAULT 0,description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_permission_code ON sys_permission(lower(permission_code)) WHERE deleted_at IS NULL;
CREATE TABLE sys_role_permission (role_id BIGINT REFERENCES sys_role(id),permission_id BIGINT REFERENCES sys_permission(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(role_id,permission_id));
CREATE TABLE sys_role_data_scope (id BIGINT PRIMARY KEY,role_id BIGINT REFERENCES sys_role(id),scope_type VARCHAR(32) NOT NULL,department_id BIGINT REFERENCES sys_department(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sys_permission_field (id BIGINT PRIMARY KEY,permission_id BIGINT REFERENCES sys_permission(id),field_code VARCHAR(128) NOT NULL,field_mode VARCHAR(32) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(permission_id,field_code));
CREATE TABLE sys_session (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES sys_user(id),refresh_token_hash VARCHAR(255),session_status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',ip INET,user_agent TEXT,device_type VARCHAR(32),login_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_active_at TIMESTAMPTZ,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,revoke_reason VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_sys_session_user ON sys_session(user_id);
CREATE TABLE sys_mfa_factor (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES sys_user(id),factor_type VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',secret_ciphertext TEXT,verified_at TIMESTAMPTZ,last_used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sys_password_history (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES sys_user(id),password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- DICTIONARY / CONFIG / FEATURE FLAG
CREATE TABLE sys_dict_type (id BIGINT PRIMARY KEY,dict_code VARCHAR(128) NOT NULL,dict_name VARCHAR(128) NOT NULL,description VARCHAR(500),status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_dict_type_code ON sys_dict_type(lower(dict_code)) WHERE deleted_at IS NULL;
CREATE TABLE sys_dict_item (id BIGINT PRIMARY KEY,dict_type_id BIGINT REFERENCES sys_dict_type(id),item_label VARCHAR(128) NOT NULL,item_value VARCHAR(255) NOT NULL,item_code VARCHAR(128),sort_order INT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',is_default BOOLEAN NOT NULL DEFAULT FALSE,description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_dict_item_value ON sys_dict_item(dict_type_id,item_value) WHERE deleted_at IS NULL;
CREATE TABLE sys_config (id BIGINT PRIMARY KEY,config_key VARCHAR(255) NOT NULL,config_name VARCHAR(128) NOT NULL,config_group VARCHAR(64) NOT NULL,value_type VARCHAR(32) NOT NULL,config_value TEXT,default_value TEXT,editable BOOLEAN NOT NULL DEFAULT TRUE,requires_restart BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',description VARCHAR(500),version BIGINT NOT NULL DEFAULT 1,effective_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_config_key ON sys_config(lower(config_key)) WHERE deleted_at IS NULL;
CREATE TABLE sys_feature_flag (id BIGINT PRIMARY KEY,flag_key VARCHAR(128) NOT NULL,flag_name VARCHAR(128) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,strategy VARCHAR(32) NOT NULL DEFAULT 'GLOBAL',percentage INT,conditions JSONB,description VARCHAR(500),version BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CHECK(percentage IS NULL OR percentage BETWEEN 0 AND 100));
CREATE UNIQUE INDEX uq_sys_feature_flag_key ON sys_feature_flag(lower(flag_key)) WHERE deleted_at IS NULL;

-- BUSINESS USER
CREATE TABLE biz_user (id BIGINT PRIMARY KEY,username VARCHAR(64),nickname VARCHAR(128) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',email VARCHAR(320),phone VARCHAR(32),avatar_url TEXT,registered_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_login_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_biz_user_username ON biz_user(lower(username)) WHERE username IS NOT NULL AND deleted_at IS NULL;
CREATE TABLE biz_user_profile (user_id BIGINT PRIMARY KEY REFERENCES biz_user(id),gender VARCHAR(16),birthday DATE,bio VARCHAR(1000),timezone VARCHAR(64),locale VARCHAR(32),preferences JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_user_login_identity (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),identity_type VARCHAR(32) NOT NULL,identity_value VARCHAR(255) NOT NULL,verified BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(identity_type,identity_value));
CREATE TABLE biz_user_password_history (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_user_verification (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),verification_type VARCHAR(32) NOT NULL,target_hash VARCHAR(255),code_hash VARCHAR(255),expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,attempt_count INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_user_session (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),refresh_token_hash VARCHAR(255),session_status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',anonymous_id_hash VARCHAR(128),ip INET,user_agent TEXT,device_type VARCHAR(32),login_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_active_at TIMESTAMPTZ,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,revoke_reason VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_user_login_log (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),identity_type VARCHAR(32),success BOOLEAN NOT NULL,failure_code VARCHAR(64),ip INET,user_agent TEXT,anonymous_id_hash VARCHAR(128),occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- GROWTH / POINTS / LEVEL / COSMETICS
CREATE TABLE biz_user_level (id BIGINT PRIMARY KEY,level_code VARCHAR(64) NOT NULL,level_name VARCHAR(128) NOT NULL,level_no INT NOT NULL,min_growth_points BIGINT NOT NULL,max_growth_points BIGINT,icon_url TEXT,description VARCHAR(500),status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,UNIQUE(level_no));
CREATE TABLE biz_user_growth_account (user_id BIGINT PRIMARY KEY REFERENCES biz_user(id),total_growth_points BIGINT NOT NULL DEFAULT 0,current_level_id BIGINT REFERENCES biz_user_level(id),version BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_user_point_account (user_id BIGINT PRIMARY KEY REFERENCES biz_user(id),balance BIGINT NOT NULL DEFAULT 0,total_earned BIGINT NOT NULL DEFAULT 0,total_spent BIGINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(balance>=0));
CREATE TABLE biz_growth_rule (id BIGINT PRIMARY KEY,rule_code VARCHAR(128) NOT NULL,rule_name VARCHAR(128) NOT NULL,event_code VARCHAR(128) NOT NULL,growth_points BIGINT NOT NULL,daily_limit BIGINT,cooldown_seconds INT,enabled BOOLEAN NOT NULL DEFAULT TRUE,conditions JSONB,description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_growth_rule_code ON biz_growth_rule(lower(rule_code)) WHERE deleted_at IS NULL;
CREATE TABLE biz_point_rule (id BIGINT PRIMARY KEY,rule_code VARCHAR(128) NOT NULL,rule_name VARCHAR(128) NOT NULL,event_code VARCHAR(128) NOT NULL,points BIGINT NOT NULL,daily_limit BIGINT,cooldown_seconds INT,enabled BOOLEAN NOT NULL DEFAULT TRUE,conditions JSONB,description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_point_rule_code ON biz_point_rule(lower(rule_code)) WHERE deleted_at IS NULL;
CREATE TABLE biz_growth_event (id BIGINT PRIMARY KEY,event_id VARCHAR(128) NOT NULL,idempotency_key VARCHAR(255) NOT NULL,user_id BIGINT REFERENCES biz_user(id),event_code VARCHAR(128) NOT NULL,source_type VARCHAR(64) NOT NULL,source_id VARCHAR(128),growth_points BIGINT NOT NULL,metadata JSONB,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(event_id),UNIQUE(idempotency_key));
CREATE TABLE biz_user_growth_transaction (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),event_id BIGINT REFERENCES biz_growth_event(id),delta_points BIGINT NOT NULL,balance_after BIGINT NOT NULL,transaction_type VARCHAR(32) NOT NULL,reason VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_point_transaction (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),event_id VARCHAR(128),idempotency_key VARCHAR(255),delta_points BIGINT NOT NULL,balance_after BIGINT NOT NULL,transaction_type VARCHAR(32) NOT NULL,source_type VARCHAR(64),source_id VARCHAR(128),reason VARCHAR(255),metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX uq_point_tx_idempotency ON biz_point_transaction(idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TABLE biz_user_level_history (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),from_level_id BIGINT REFERENCES biz_user_level(id),to_level_id BIGINT REFERENCES biz_user_level(id),growth_points BIGINT NOT NULL,reason VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_user_level_benefit (id BIGINT PRIMARY KEY,level_id BIGINT REFERENCES biz_user_level(id),benefit_type VARCHAR(64) NOT NULL,benefit_code VARCHAR(128) NOT NULL,benefit_value JSONB,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(level_id,benefit_type,benefit_code));
CREATE TABLE biz_cosmetic (id BIGINT PRIMARY KEY,cosmetic_code VARCHAR(128) NOT NULL,cosmetic_name VARCHAR(128) NOT NULL,cosmetic_type VARCHAR(32) NOT NULL,asset_url TEXT,metadata JSONB,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_cosmetic_code ON biz_cosmetic(lower(cosmetic_code)) WHERE deleted_at IS NULL;
CREATE TABLE biz_user_cosmetic (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),cosmetic_id BIGINT REFERENCES biz_cosmetic(id),obtained_at TIMESTAMPTZ NOT NULL DEFAULT now(),source_type VARCHAR(64),source_id VARCHAR(128),UNIQUE(user_id,cosmetic_id));
CREATE TABLE biz_user_equipment (user_id BIGINT PRIMARY KEY REFERENCES biz_user(id),avatar_cosmetic_id BIGINT REFERENCES biz_cosmetic(id),avatar_frame_cosmetic_id BIGINT REFERENCES biz_cosmetic(id),crown_cosmetic_id BIGINT REFERENCES biz_cosmetic(id),badge_cosmetic_id BIGINT REFERENCES biz_cosmetic(id),title_cosmetic_id BIGINT REFERENCES biz_cosmetic(id),name_effect_cosmetic_id BIGINT REFERENCES biz_cosmetic(id),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE biz_task (id BIGINT PRIMARY KEY,task_code VARCHAR(128) NOT NULL,task_name VARCHAR(128) NOT NULL,task_type VARCHAR(32) NOT NULL,conditions JSONB NOT NULL,reward JSONB,start_at TIMESTAMPTZ,end_at TIMESTAMPTZ,repeatable BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_task_code ON biz_task(lower(task_code)) WHERE deleted_at IS NULL;
CREATE TABLE biz_user_task (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),task_id BIGINT REFERENCES biz_task(id),progress JSONB,status VARCHAR(16) NOT NULL DEFAULT 'IN_PROGRESS',completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,task_id));
CREATE TABLE biz_achievement (id BIGINT PRIMARY KEY,achievement_code VARCHAR(128) NOT NULL,achievement_name VARCHAR(128) NOT NULL,conditions JSONB NOT NULL,reward JSONB,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_achievement_code ON biz_achievement(lower(achievement_code)) WHERE deleted_at IS NULL;
CREATE TABLE biz_user_achievement (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),achievement_id BIGINT REFERENCES biz_achievement(id),achieved_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,achievement_id));

-- TOOLS
CREATE TABLE tool_category (id BIGINT PRIMARY KEY,category_code VARCHAR(64) NOT NULL,category_name VARCHAR(128) NOT NULL,description VARCHAR(500),icon_url TEXT,sort_order INT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_tool_category_code ON tool_category(lower(category_code)) WHERE deleted_at IS NULL;
CREATE TABLE tool (id BIGINT PRIMARY KEY,code VARCHAR(128) NOT NULL,name VARCHAR(128) NOT NULL,slug VARCHAR(160) NOT NULL,category_id BIGINT REFERENCES tool_category(id),icon TEXT,summary VARCHAR(500),description TEXT,keywords JSONB,tags JSONB,component_key VARCHAR(128) NOT NULL,execution_mode VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',sort_order INT NOT NULL DEFAULT 0,current_version_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_tool_code ON tool(lower(code)) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_tool_slug ON tool(lower(slug)) WHERE deleted_at IS NULL;
CREATE TABLE tool_version (id BIGINT PRIMARY KEY,tool_id BIGINT REFERENCES tool(id),version VARCHAR(64) NOT NULL,release_status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',changelog TEXT,runtime_config JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),published_at TIMESTAMPTZ,UNIQUE(tool_id,version));
ALTER TABLE tool ADD CONSTRAINT fk_tool_current_version FOREIGN KEY(current_version_id) REFERENCES tool_version(id);
CREATE TABLE tool_component_registry (id BIGINT PRIMARY KEY,component_key VARCHAR(128) NOT NULL UNIQUE,component_name VARCHAR(128) NOT NULL,frontend_component_key VARCHAR(255) NOT NULL,execution_mode VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE tool_access_policy (id BIGINT PRIMARY KEY,tool_id BIGINT REFERENCES tool(id),subject_type VARCHAR(32) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,daily_limit BIGINT,rate_limit_per_minute INT,concurrency_limit INT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tool_id,subject_type));
CREATE TABLE tool_usage_event (id BIGINT PRIMARY KEY,tool_id BIGINT REFERENCES tool(id),tool_version_id BIGINT REFERENCES tool_version(id),subject_type VARCHAR(32) NOT NULL,user_id BIGINT REFERENCES biz_user(id),anonymous_id_hash VARCHAR(128),execution_mode VARCHAR(32) NOT NULL,success BOOLEAN NOT NULL,duration_ms BIGINT,source VARCHAR(64),trace_id VARCHAR(128),request_id VARCHAR(128),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_tool_usage_tool_time ON tool_usage_event(tool_id,created_at DESC);
CREATE TABLE tool_usage_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,tool_id BIGINT REFERENCES tool(id),total_count BIGINT NOT NULL DEFAULT 0,success_count BIGINT NOT NULL DEFAULT 0,failure_count BIGINT NOT NULL DEFAULT 0,guest_count BIGINT NOT NULL DEFAULT 0,user_count BIGINT NOT NULL DEFAULT 0,unique_user_count BIGINT NOT NULL DEFAULT 0,unique_guest_count BIGINT NOT NULL DEFAULT 0,avg_duration_ms NUMERIC(18,2),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,tool_id));
CREATE TABLE tool_popularity_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,window_days INT NOT NULL,tool_id BIGINT REFERENCES tool(id),usage_count BIGINT NOT NULL DEFAULT 0,unique_user_count BIGINT NOT NULL DEFAULT 0,rank_no INT,score NUMERIC(20,6),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,window_days,tool_id));
CREATE TABLE tool_recent_usage (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),tool_id BIGINT REFERENCES tool(id),last_used_at TIMESTAMPTZ NOT NULL DEFAULT now(),use_count BIGINT NOT NULL DEFAULT 1,UNIQUE(user_id,tool_id));

-- BLOG
CREATE TABLE blog_author (id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES biz_user(id),author_name VARCHAR(128) NOT NULL,bio VARCHAR(1000),avatar_url TEXT,status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',approved_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE blog_author_application (id BIGINT PRIMARY KEY,user_id BIGINT REFERENCES biz_user(id),application_reason TEXT,status VARCHAR(32) NOT NULL DEFAULT 'PENDING',reviewer_id BIGINT REFERENCES sys_user(id),review_reason VARCHAR(1000),applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ);
CREATE TABLE blog_category (id BIGINT PRIMARY KEY,category_code VARCHAR(64) NOT NULL,category_name VARCHAR(128) NOT NULL,description VARCHAR(500),sort_order INT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE blog_article (id BIGINT PRIMARY KEY,author_id BIGINT NOT NULL REFERENCES blog_author(id),category_id BIGINT REFERENCES blog_category(id),title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL,summary VARCHAR(1000),cover_url TEXT,content_markdown TEXT,content_html TEXT,status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',review_status VARCHAR(32) NOT NULL DEFAULT 'NOT_REQUIRED',reviewer_id BIGINT REFERENCES sys_user(id),reviewed_at TIMESTAMPTZ,published_at TIMESTAMPTZ,view_count BIGINT NOT NULL DEFAULT 0,like_count BIGINT NOT NULL DEFAULT 0,favorite_count BIGINT NOT NULL DEFAULT 0,comment_count BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_blog_article_slug ON blog_article(lower(slug)) WHERE deleted_at IS NULL;
CREATE TABLE blog_article_tag (id BIGINT PRIMARY KEY,article_id BIGINT REFERENCES blog_article(id),tag_name VARCHAR(128) NOT NULL,UNIQUE(article_id,tag_name));
CREATE TABLE blog_article_like (user_id BIGINT REFERENCES biz_user(id),article_id BIGINT REFERENCES blog_article(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,article_id));
CREATE TABLE blog_article_favorite (user_id BIGINT REFERENCES biz_user(id),article_id BIGINT REFERENCES blog_article(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,article_id));
CREATE TABLE blog_comment (id BIGINT PRIMARY KEY,article_id BIGINT REFERENCES blog_article(id),user_id BIGINT REFERENCES biz_user(id),parent_id BIGINT REFERENCES blog_comment(id),content TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',reviewer_id BIGINT REFERENCES sys_user(id),reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE blog_user_follow (follower_user_id BIGINT REFERENCES biz_user(id),followed_user_id BIGINT REFERENCES biz_user(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(follower_user_id,followed_user_id),CHECK(follower_user_id<>followed_user_id));

-- ANALYTICS
CREATE TABLE behavior_event (id BIGINT PRIMARY KEY,event_id VARCHAR(128) NOT NULL,event_code VARCHAR(128) NOT NULL,event_name VARCHAR(255),anonymous_id_hash VARCHAR(128),user_id BIGINT REFERENCES biz_user(id),session_id BIGINT,platform VARCHAR(32),device_type VARCHAR(32),os VARCHAR(64),browser VARCHAR(128),app_code VARCHAR(64),app_version VARCHAR(64),page_code VARCHAR(128),page_url TEXT,referrer TEXT,module VARCHAR(64),resource_type VARCHAR(64),resource_id VARCHAR(128),properties JSONB,trace_id VARCHAR(128),request_id VARCHAR(128),occurred_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(event_id));
CREATE INDEX idx_behavior_event_code_time ON behavior_event(event_code,occurred_at DESC);
CREATE INDEX idx_behavior_event_user_time ON behavior_event(user_id,occurred_at DESC);
CREATE TABLE behavior_event_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,event_code VARCHAR(128) NOT NULL,total_count BIGINT NOT NULL DEFAULT 0,unique_user_count BIGINT NOT NULL DEFAULT 0,unique_anonymous_count BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,event_code));
CREATE TABLE behavior_user_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,user_id BIGINT REFERENCES biz_user(id),anonymous_id_hash VARCHAR(128),event_count BIGINT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,first_event_at TIMESTAMPTZ,last_event_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,user_id,anonymous_id_hash));
CREATE TABLE behavior_page_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,page_code VARCHAR(128) NOT NULL,view_count BIGINT NOT NULL DEFAULT 0,unique_user_count BIGINT NOT NULL DEFAULT 0,unique_anonymous_count BIGINT NOT NULL DEFAULT 0,avg_duration_ms NUMERIC(18,2),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,page_code));
CREATE TABLE behavior_tool_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,tool_id BIGINT REFERENCES tool(id),view_count BIGINT NOT NULL DEFAULT 0,start_count BIGINT NOT NULL DEFAULT 0,execute_count BIGINT NOT NULL DEFAULT 0,success_count BIGINT NOT NULL DEFAULT 0,failure_count BIGINT NOT NULL DEFAULT 0,copy_count BIGINT NOT NULL DEFAULT 0,download_count BIGINT NOT NULL DEFAULT 0,unique_user_count BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,tool_id));
CREATE TABLE behavior_search_daily (id BIGINT PRIMARY KEY,stat_date DATE NOT NULL,search_type VARCHAR(64) NOT NULL,keyword_hash VARCHAR(128) NOT NULL,search_count BIGINT NOT NULL DEFAULT 0,result_click_count BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(stat_date,search_type,keyword_hash));
CREATE TABLE behavior_funnel (id BIGINT PRIMARY KEY,funnel_code VARCHAR(128) NOT NULL,funnel_name VARCHAR(128) NOT NULL,step_no INT NOT NULL,step_code VARCHAR(128) NOT NULL,event_code VARCHAR(128) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(funnel_code,step_no));
CREATE TABLE behavior_identity_merge (id BIGINT PRIMARY KEY,anonymous_id_hash VARCHAR(128) NOT NULL,user_id BIGINT REFERENCES biz_user(id),first_seen_at TIMESTAMPTZ,merged_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(anonymous_id_hash,user_id));

-- OUTBOX / IDEMPOTENCY / JOB / NOTIFICATION
CREATE TABLE sys_outbox_event (id BIGINT PRIMARY KEY,event_id VARCHAR(128) NOT NULL,event_type VARCHAR(128) NOT NULL,aggregate_type VARCHAR(128),aggregate_id VARCHAR(128),payload JSONB NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'PENDING',attempt_count INT NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ,last_error TEXT,trace_id VARCHAR(128),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(event_id));
CREATE INDEX idx_outbox_status_available ON sys_outbox_event(status,available_at);
CREATE TABLE sys_idempotency_record (id BIGINT PRIMARY KEY,idempotency_key VARCHAR(255) NOT NULL,scope VARCHAR(128) NOT NULL,request_hash VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'PROCESSING',response_code INT,response_body JSONB,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(scope,idempotency_key));
CREATE TABLE sys_job (id BIGINT PRIMARY KEY,job_code VARCHAR(128) NOT NULL,job_name VARCHAR(128) NOT NULL,job_type VARCHAR(64) NOT NULL,payload JSONB,status VARCHAR(32) NOT NULL DEFAULT 'PENDING',priority INT NOT NULL DEFAULT 0,attempt_count INT NOT NULL DEFAULT 0,max_attempts INT NOT NULL DEFAULT 3,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ,last_error TEXT,trace_id VARCHAR(128),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_sys_job_status_available ON sys_job(status,available_at);
CREATE TABLE sys_job_definition (id BIGINT PRIMARY KEY,job_code VARCHAR(128) NOT NULL UNIQUE,job_name VARCHAR(128) NOT NULL,cron_expression VARCHAR(128),enabled BOOLEAN NOT NULL DEFAULT TRUE,payload JSONB,description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sys_notification (id BIGINT PRIMARY KEY,user_type VARCHAR(32) NOT NULL,user_id BIGINT NOT NULL,notification_type VARCHAR(64) NOT NULL,title VARCHAR(255) NOT NULL,content TEXT NOT NULL,payload JSONB,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_notification_user_time ON sys_notification(user_type,user_id,created_at DESC);

-- FILE / EXPORT / RISK
CREATE TABLE sys_file (id BIGINT PRIMARY KEY,owner_type VARCHAR(32),owner_id BIGINT,storage_provider VARCHAR(32) NOT NULL,bucket VARCHAR(255),object_key VARCHAR(1024) NOT NULL,original_name VARCHAR(255),content_type VARCHAR(255),size_bytes BIGINT,checksum VARCHAR(128),status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_sys_file_object ON sys_file(storage_provider,bucket,object_key);
CREATE TABLE sys_export_job (id BIGINT PRIMARY KEY,requested_by BIGINT REFERENCES sys_user(id),export_type VARCHAR(64) NOT NULL,filter_json JSONB,status VARCHAR(32) NOT NULL DEFAULT 'PENDING',file_id BIGINT REFERENCES sys_file(id),row_count BIGINT,error_message TEXT,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);
CREATE TABLE risk_rule (id BIGINT PRIMARY KEY,rule_code VARCHAR(128) NOT NULL,rule_name VARCHAR(128) NOT NULL,rule_type VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,threshold BIGINT,window_seconds INT,action VARCHAR(64) NOT NULL,conditions JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_risk_rule_code ON risk_rule(lower(rule_code)) WHERE deleted_at IS NULL;

-- LOG / AUDIT
CREATE TABLE sys_audit_log (id BIGINT PRIMARY KEY,trace_id VARCHAR(128),request_id VARCHAR(128),operator_id BIGINT REFERENCES sys_user(id),operator_username VARCHAR(64),action VARCHAR(128) NOT NULL,resource_type VARCHAR(128),resource_id VARCHAR(128),before_data JSONB,after_data JSONB,result VARCHAR(32) NOT NULL,error_code VARCHAR(64),ip INET,user_agent TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_resource ON sys_audit_log(resource_type,resource_id,created_at DESC);
CREATE INDEX idx_audit_trace ON sys_audit_log(trace_id);
CREATE TABLE sys_access_log (id BIGINT PRIMARY KEY,trace_id VARCHAR(128),request_id VARCHAR(128),user_id BIGINT,method VARCHAR(16) NOT NULL,path TEXT NOT NULL,status_code INT,ip INET,user_agent TEXT,duration_ms BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sys_security_log (id BIGINT PRIMARY KEY,trace_id VARCHAR(128),user_id BIGINT,event_type VARCHAR(128) NOT NULL,result VARCHAR(32) NOT NULL,error_code VARCHAR(64),ip INET,user_agent TEXT,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sys_operation_log (id BIGINT PRIMARY KEY,trace_id VARCHAR(128),request_id VARCHAR(128),operator_id BIGINT REFERENCES sys_user(id),operation VARCHAR(128) NOT NULL,resource_type VARCHAR(128),resource_id VARCHAR(128),result VARCHAR(32) NOT NULL,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sys_application_log (id BIGINT PRIMARY KEY,trace_id VARCHAR(128),level VARCHAR(16) NOT NULL,logger_name VARCHAR(255),message TEXT NOT NULL,exception_type VARCHAR(255),metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- Application invariants not fully expressible in DDL:
-- 1) At least one usable SUPER_ADMIN remains.
-- 2) Non-super admins cannot kick SUPER_ADMIN.
-- 3) Department scope is own + descendants.
-- 4) New admin user must_change_password=true.
-- 5) Permission changes effective immediately.
-- 6) Multiple roles union permissions.
-- 7) Backend authorization is authoritative.
-- 8) No tenant_id.
-- 9) BIGINT API IDs are strings.
-- 10) Password/MFA secret/token are never logged.

