-- ---------------------------------------------------------------------------
-- Ops monitoring (vctn-api/app/ops)
--
-- Generated from the ORM models so the baseline stays the single source of
-- truth for the ops schema. BIGINT snowflake identifiers, UTC timestamps, no
-- tenant_id.
-- ---------------------------------------------------------------------------

CREATE TABLE ops_host_group (id BIGINT NOT NULL PRIMARY KEY,group_code VARCHAR(64) NOT NULL,group_name VARCHAR(128) NOT NULL,description VARCHAR(500),sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_host_group_code UNIQUE(group_code));
CREATE TABLE ops_host (id BIGINT NOT NULL PRIMARY KEY,hostname VARCHAR(128) NOT NULL,display_name VARCHAR(128),ip_address VARCHAR(64),os_type VARCHAR(32),os_version VARCHAR(64),cpu_cores INTEGER,memory_total_mb BIGINT,disk_total_gb BIGINT,environment VARCHAR(32) NOT NULL DEFAULT 'PRODUCTION',host_group_id BIGINT REFERENCES ops_host_group(id),agent_id BIGINT,status VARCHAR(32) NOT NULL DEFAULT 'UNKNOWN',last_seen_at TIMESTAMPTZ,tags JSONB,metadata_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_host_hostname UNIQUE(hostname));
CREATE INDEX ix_ops_host_environment ON ops_host(environment);
CREATE INDEX ix_ops_host_status ON ops_host(status);
CREATE TABLE ops_agent (id BIGINT NOT NULL PRIMARY KEY,agent_code VARCHAR(64) NOT NULL,agent_name VARCHAR(128) NOT NULL,host_id BIGINT REFERENCES ops_host(id),token_hash VARCHAR(255) NOT NULL,version VARCHAR(32),ip_address VARCHAR(64),status VARCHAR(32) NOT NULL DEFAULT 'UNKNOWN',enabled BOOLEAN NOT NULL DEFAULT true,last_heartbeat_at TIMESTAMPTZ,registered_at TIMESTAMPTZ,metadata_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_agent_code UNIQUE(agent_code));
CREATE INDEX ix_ops_agent_status ON ops_agent(status);
CREATE TABLE ops_agent_heartbeat (id BIGINT NOT NULL PRIMARY KEY,agent_id BIGINT NOT NULL REFERENCES ops_agent(id),cpu_usage FLOAT,memory_usage FLOAT,disk_usage FLOAT,load1 FLOAT,load5 FLOAT,load15 FLOAT,net_rx_bytes BIGINT,net_tx_bytes BIGINT,uptime_seconds BIGINT,collected_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_ops_agent_heartbeat_agent_collected ON ops_agent_heartbeat(agent_id,collected_at);
CREATE TABLE ops_alert_rule (id BIGINT NOT NULL PRIMARY KEY,rule_code VARCHAR(64) NOT NULL,rule_name VARCHAR(128) NOT NULL,alert_type VARCHAR(64) NOT NULL,metric_key VARCHAR(128) NOT NULL,condition VARCHAR(16) NOT NULL DEFAULT 'GT',threshold FLOAT NOT NULL,duration_seconds INTEGER NOT NULL DEFAULT 300,severity VARCHAR(32) NOT NULL DEFAULT 'WARNING',scope_type VARCHAR(32) NOT NULL DEFAULT 'GLOBAL',scope_id BIGINT,notification_policy JSONB,enabled BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_alert_rule_code UNIQUE(rule_code));
CREATE INDEX ix_ops_alert_rule_type ON ops_alert_rule(alert_type);
CREATE TABLE ops_service (id BIGINT NOT NULL PRIMARY KEY,service_code VARCHAR(64) NOT NULL,service_name VARCHAR(128) NOT NULL,service_type VARCHAR(32) NOT NULL DEFAULT 'APPLICATION',environment VARCHAR(32) NOT NULL DEFAULT 'PRODUCTION',host_id BIGINT REFERENCES ops_host(id),status VARCHAR(32) NOT NULL DEFAULT 'UNKNOWN',last_check_at TIMESTAMPTZ,availability_rate FLOAT,error_rate FLOAT,avg_latency_ms FLOAT,tags JSONB,metadata_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_service_code UNIQUE(service_code));
CREATE INDEX ix_ops_service_environment ON ops_service(environment);
CREATE INDEX ix_ops_service_status ON ops_service(status);
CREATE TABLE ops_alert (id BIGINT NOT NULL PRIMARY KEY,fingerprint VARCHAR(128) NOT NULL,rule_id BIGINT REFERENCES ops_alert_rule(id),alert_type VARCHAR(64) NOT NULL,severity VARCHAR(32) NOT NULL DEFAULT 'WARNING',status VARCHAR(32) NOT NULL DEFAULT 'TRIGGERED',resource_type VARCHAR(64),resource_id BIGINT,host_id BIGINT,service_id BIGINT REFERENCES ops_service(id),metric_key VARCHAR(128),metric_value FLOAT,threshold FLOAT,description VARCHAR(1000),trace_id VARCHAR(64),triggered_at TIMESTAMPTZ NOT NULL DEFAULT now(),acknowledged_at TIMESTAMPTZ,acknowledged_by BIGINT,silenced_until TIMESTAMPTZ,silence_reason VARCHAR(500),resolved_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uq_ops_alert_fingerprint UNIQUE(fingerprint));
CREATE INDEX ix_ops_alert_status_severity ON ops_alert(status,severity);
CREATE INDEX ix_ops_alert_triggered ON ops_alert(triggered_at);
CREATE TABLE ops_alert_history (id BIGINT NOT NULL PRIMARY KEY,alert_id BIGINT NOT NULL REFERENCES ops_alert(id),from_status VARCHAR(32),to_status VARCHAR(32) NOT NULL,actor_id BIGINT,actor_username VARCHAR(64),note VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_ops_alert_history_alert ON ops_alert_history(alert_id,created_at);
CREATE TABLE ops_notification_channel (id BIGINT NOT NULL PRIMARY KEY,channel_code VARCHAR(64) NOT NULL,channel_name VARCHAR(128) NOT NULL,channel_type VARCHAR(32) NOT NULL DEFAULT 'WEBHOOK',config JSONB NOT NULL,enabled BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_notification_channel_code UNIQUE(channel_code));
CREATE TABLE ops_alert_notification (id BIGINT NOT NULL PRIMARY KEY,alert_id BIGINT NOT NULL REFERENCES ops_alert(id),channel_id BIGINT REFERENCES ops_notification_channel(id),channel_code VARCHAR(64) NOT NULL,receiver VARCHAR(255),status VARCHAR(32) NOT NULL DEFAULT 'PENDING',retry_count INTEGER NOT NULL DEFAULT 0,sent_at TIMESTAMPTZ,error_message VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_ops_alert_notification_alert ON ops_alert_notification(alert_id);
CREATE INDEX ix_ops_alert_notification_status ON ops_alert_notification(status);
CREATE TABLE ops_availability_check (id BIGINT NOT NULL PRIMARY KEY,check_code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,check_type VARCHAR(16) NOT NULL,target VARCHAR(500) NOT NULL,service_id BIGINT REFERENCES ops_service(id),environment VARCHAR(32) NOT NULL DEFAULT 'PRODUCTION',timeout_ms INTEGER NOT NULL DEFAULT 5000,interval_seconds INTEGER NOT NULL DEFAULT 60,expected_status INTEGER,enabled BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_availability_check_code UNIQUE(check_code));
CREATE INDEX ix_ops_availability_check_type ON ops_availability_check(check_type);
CREATE TABLE ops_availability_result (id BIGINT NOT NULL PRIMARY KEY,check_id BIGINT NOT NULL REFERENCES ops_availability_check(id),success BOOLEAN NOT NULL,latency_ms FLOAT,status_code INTEGER,error_message VARCHAR(1000),detail JSONB,checked_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_ops_availability_result_check_time ON ops_availability_result(check_id,checked_at);
CREATE TABLE ops_dashboard (id BIGINT NOT NULL PRIMARY KEY,dashboard_code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,description VARCHAR(500),is_default BOOLEAN NOT NULL DEFAULT false,created_by BIGINT,created_by_username VARCHAR(64),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_dashboard_code UNIQUE(dashboard_code));
CREATE TABLE ops_dashboard_widget (id BIGINT NOT NULL PRIMARY KEY,dashboard_id BIGINT NOT NULL REFERENCES ops_dashboard(id),widget_type VARCHAR(32) NOT NULL,title VARCHAR(128) NOT NULL,metric_key VARCHAR(128),options JSONB,position_x INTEGER NOT NULL DEFAULT 0,position_y INTEGER NOT NULL DEFAULT 0,width INTEGER NOT NULL DEFAULT 6,height INTEGER NOT NULL DEFAULT 4,sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE INDEX ix_ops_dashboard_widget_dashboard ON ops_dashboard_widget(dashboard_id);
CREATE TABLE ops_endpoint (id BIGINT NOT NULL PRIMARY KEY,endpoint_key VARCHAR(255) NOT NULL,http_method VARCHAR(16) NOT NULL,path_pattern VARCHAR(500) NOT NULL,service_id BIGINT REFERENCES ops_service(id),environment VARCHAR(32) NOT NULL DEFAULT 'PRODUCTION',is_monitored BOOLEAN NOT NULL DEFAULT true,request_count BIGINT NOT NULL DEFAULT 0,error_count BIGINT NOT NULL DEFAULT 0,avg_latency_ms FLOAT,p95_latency_ms FLOAT,last_seen_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_endpoint_key UNIQUE(endpoint_key));
CREATE INDEX ix_ops_endpoint_service ON ops_endpoint(service_id);
CREATE TABLE ops_environment (id BIGINT NOT NULL PRIMARY KEY,env_code VARCHAR(32) NOT NULL,env_name VARCHAR(64) NOT NULL,description VARCHAR(500),sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_environment_code UNIQUE(env_code));
CREATE TABLE ops_event (id BIGINT NOT NULL PRIMARY KEY,event_id VARCHAR(64) NOT NULL,event_type VARCHAR(64) NOT NULL,source VARCHAR(64) NOT NULL,resource_type VARCHAR(64),resource_id BIGINT,severity VARCHAR(32) NOT NULL DEFAULT 'INFO',message VARCHAR(1000),trace_id VARCHAR(64),request_id VARCHAR(64),occurred_at TIMESTAMPTZ NOT NULL,metadata_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uq_ops_event_id UNIQUE(event_id));
CREATE INDEX ix_ops_event_occurred ON ops_event(occurred_at);
CREATE INDEX ix_ops_event_trace ON ops_event(trace_id);
CREATE INDEX ix_ops_event_type_occurred ON ops_event(event_type,occurred_at);
CREATE TABLE ops_maintenance_window (id BIGINT NOT NULL PRIMARY KEY,window_code VARCHAR(64) NOT NULL,title VARCHAR(200) NOT NULL,reason VARCHAR(1000),scope_type VARCHAR(32) NOT NULL DEFAULT 'GLOBAL',scope_id BIGINT,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,suppress_alerts BOOLEAN NOT NULL DEFAULT true,enabled BOOLEAN NOT NULL DEFAULT true,created_by BIGINT,created_by_username VARCHAR(64),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT ck_ops_maintenance_window_range CHECK(ends_at > starts_at),CONSTRAINT uq_ops_maintenance_window_code UNIQUE(window_code));
CREATE INDEX ix_ops_maintenance_window_range ON ops_maintenance_window(starts_at,ends_at);
CREATE TABLE ops_metric_daily (id BIGINT NOT NULL PRIMARY KEY,metric_key VARCHAR(128) NOT NULL,dimension_key VARCHAR(255) NOT NULL,bucket_at TIMESTAMPTZ NOT NULL,avg_value FLOAT,min_value FLOAT,max_value FLOAT,sum_value FLOAT,sample_count INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uq_ops_metric_daily_bucket UNIQUE(metric_key,dimension_key,bucket_at));
CREATE INDEX ix_ops_metric_daily_bucket ON ops_metric_daily(bucket_at);
CREATE TABLE ops_metric_definition (id BIGINT NOT NULL PRIMARY KEY,metric_key VARCHAR(128) NOT NULL,metric_name VARCHAR(128) NOT NULL,metric_type VARCHAR(32) NOT NULL,unit VARCHAR(32),description VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_metric_definition_key UNIQUE(metric_key));
CREATE TABLE ops_metric_hourly (id BIGINT NOT NULL PRIMARY KEY,metric_key VARCHAR(128) NOT NULL,dimension_key VARCHAR(255) NOT NULL,bucket_at TIMESTAMPTZ NOT NULL,avg_value FLOAT,min_value FLOAT,max_value FLOAT,sum_value FLOAT,sample_count INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uq_ops_metric_hourly_bucket UNIQUE(metric_key,dimension_key,bucket_at));
CREATE INDEX ix_ops_metric_hourly_bucket ON ops_metric_hourly(bucket_at);
CREATE TABLE ops_metric_sample (id BIGINT NOT NULL PRIMARY KEY,metric_key VARCHAR(128) NOT NULL,host_id BIGINT,service_id BIGINT,endpoint_id BIGINT,environment VARCHAR(32) NOT NULL DEFAULT 'PRODUCTION',value FLOAT NOT NULL,labels JSONB,collected_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_ops_metric_sample_collected ON ops_metric_sample(collected_at);
CREATE INDEX ix_ops_metric_sample_key_collected ON ops_metric_sample(metric_key,collected_at);
CREATE TABLE ops_monitor (id BIGINT NOT NULL PRIMARY KEY,monitor_code VARCHAR(64) NOT NULL,monitor_name VARCHAR(128) NOT NULL,monitor_type VARCHAR(32) NOT NULL,target_type VARCHAR(32) NOT NULL,target_id BIGINT,environment VARCHAR(32) NOT NULL DEFAULT 'PRODUCTION',enabled BOOLEAN NOT NULL DEFAULT true,metadata_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_monitor_code UNIQUE(monitor_code));
CREATE INDEX ix_ops_monitor_type ON ops_monitor(monitor_type);
CREATE TABLE ops_notification_group (id BIGINT NOT NULL PRIMARY KEY,group_code VARCHAR(64) NOT NULL,group_name VARCHAR(128) NOT NULL,channel_codes JSONB NOT NULL,receivers JSONB NOT NULL,enabled BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_notification_group_code UNIQUE(group_code));
CREATE TABLE ops_operation_record (id BIGINT NOT NULL PRIMARY KEY,operator_id BIGINT,operator_username VARCHAR(64),action VARCHAR(64) NOT NULL,resource_type VARCHAR(64) NOT NULL,resource_id BIGINT,result VARCHAR(32) NOT NULL DEFAULT 'SUCCESS',error_message VARCHAR(1000),ip_address VARCHAR(64),user_agent VARCHAR(500),trace_id VARCHAR(64),request_id VARCHAR(64),before_data JSONB,after_data JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_ops_operation_record_action_time ON ops_operation_record(action,created_at);
CREATE INDEX ix_ops_operation_record_operator ON ops_operation_record(operator_id);
CREATE INDEX ix_ops_operation_record_trace ON ops_operation_record(trace_id);
CREATE TABLE ops_service_dependency (id BIGINT NOT NULL PRIMARY KEY,service_id BIGINT NOT NULL REFERENCES ops_service(id),depends_on_service_id BIGINT NOT NULL REFERENCES ops_service(id),dependency_type VARCHAR(32) NOT NULL DEFAULT 'CALLS',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ,CONSTRAINT uq_ops_service_dependency_pair UNIQUE(service_id,depends_on_service_id));
CREATE INDEX ix_ops_service_dependency_target ON ops_service_dependency(depends_on_service_id);
